echo "$CAN_NONE" | grep -q "Canonical:" \
    && check "canonical: absent for non-brand URL" "0" "1" \
    || check "canonical: absent for non-brand URL" "0" "0"

# Threat URL (fake domain) → NO canonical confirmation (score > 0)
