    || check "--from qr stdin: header shows ISOLATE" "0" "1"

# Help lists --from
./hlse_core --help 2>&1 | grep -q "\-\-from" && check "help: lists --from" "0" "0" \
    || check "help: lists --from" "0" "1"

# Help lists all subcommands documented in the spec
