s = d.get("severity")
assert s == 3 or s == 4, "expected 3 or 4, got " + str(s)
' && check "p80 json text: BEC ISOLATE → severity >= 3" "0" "0" \
   || check "p80 json text: BEC ISOLATE → severity >= 3" "0" "1"

# Text: SAFE → severity 0
