import sys, json
try:
    from jsonschema import validate
except ImportError:
    import sys; sys.exit(0)  # validator absent -> skip, not fail
with open("schema/hlse_scan_summary.schema.json") as f:
    schema = json.load(f)
for line in sys.stdin:
