assert not missing, "SARIF tokens absent from JSON scan: " + repr(missing)
' "$P91_DIR" && check "p91: SARIF and JSON scan pattern_id agree" "0" "0" \
   || check "p91: SARIF and JSON scan pattern_id agree" "0" "1"

