    && ./hlse_core package reqeusts pip 2>/dev/null | grep -q "prepare" \
    && check "p92 text: package advisory names --ignore-scripts + prepare" "0" "0" \
    || check "p92 text: package advisory names --ignore-scripts + prepare" "0" "1"

