printf 'Received: from mail.example.com\nReceived-SPF: pass\nFrom: a@example.com\nReply-To: a@example.com\nTo: b@example.com\nSubject: lunch\n\nlunch?\n' \
    | ./hlse_core --json email --stdin 2>/dev/null | python3 -c '
